//
// This is only a SKELETON file for the 'Rational Numbers' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const gcd = (a, b) => (b === 0 ? Math.abs(a) : gcd(b, a % b));

export class Rational {
  constructor(numerator, denominator) {
    this.numerator = numerator;
    this.denominator = denominator;
  }

  add(other) {
    return new Rational(
      this.numerator * other.denominator + other.numerator * this.denominator,
      this.denominator * other.denominator
    ).reduce();
  }

  sub(other) {
    return new Rational(
      this.numerator * other.denominator - other.numerator * this.denominator,
      this.denominator * other.denominator
    ).reduce();
  }

  mul(other) {
    return new Rational(
      this.numerator * other.numerator,
      this.denominator * other.denominator
    ).reduce();
  }

  div(other) {
    return new Rational(
      this.numerator * other.denominator,
      this.denominator * other.numerator
    ).reduce();
  }

  abs() {
    return new Rational(
      Math.abs(this.numerator),
      Math.abs(this.denominator)
    ).reduce();
  }

  exprational(power) {
    if (power >= 0) {
      return new Rational(
        this.numerator ** power,
        this.denominator ** power
      ).reduce();
    }
    return new Rational(
      this.denominator ** -power,
      this.numerator ** -power
    ).reduce();
  }

  expreal(x) {
    return Math.pow(Math.pow(x, this.numerator), 1 / this.denominator);
  }

  reduce() {
    const divisor = gcd(this.numerator, this.denominator) || 1;
    let numerator = this.numerator / divisor;
    let denominator = this.denominator / divisor;
    if (denominator < 0) {
      numerator = -numerator;
      denominator = -denominator;
    }
    return new Rational(numerator, denominator);
  }
}

